function background(){const tide=world?.theme==='tide',keep=world?.theme==='keep';const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,keep?'#171822':tide?'#19262d':'#1b202b');g.addColorStop(1,keep?'#493532':tide?'#38464a':'#51403b');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // stars / drifting cinders
