 for(let i=0;i<20;i++){let x=((i*89-frame*(i%2?.24:.12))%(W+30)+W+30)%(W+30);let y=(i*61+frame*(i%3+1)*.18)%220;rect(x,y,1,2,i%3?'#a1654e':'#d18d60')}
}
